import { useState, type FormEvent } from 'react';
import {
  JxButton,
  JxInputField,
  JxToastViewport,
  useJxToastQueue,
} from '@jinx-ui/react';

export default function SubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
  };

  return (
    <form onSubmit={submit} style={{ display: 'grid', gap: '16px', maxWidth: '360px' }}>
      <JxInputField
        label="Электронная почта"
        type="email"
        required
        placeholder="you@example.com"
        helperText="Присылаем письма не чаще раза в неделю"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
      />
      <JxButton type="submit" variant="primary">
        Подписаться
      </JxButton>
      <JxToastViewport
        items={toasts.items}
        onDismiss={toasts.dismiss}
        position="bottom-right"
      />
    </form>
  );
}

